/* Uploaded workbook registry, source pathways and dictionary, joined by canonical patient ID. */
(()=>{
let data=null,error='',tab='Patients',choice='L1',sheet='PW Low risk',query='',group='All',scope='all',patientPage=0;
const primary=p=>/^FN-\d{3}$/.test(id(p));
const inScope=p=>scope==='all'||(scope==='primary'?primary(p):!primary(p));
const sourceOf=pid=>data?.patients.find(p=>p['Patient ID']===pid)||data?.scenarios.find(c=>c.patientId===pid);
const caseKey=pid=>'USR-'+data.sourceKeys[pid];
const rowsTable=(rows,head=true)=>`<div class="scroll"><table>${rows.map((r,i)=>`<${head&&i===0?'thead':'tbody'}><tr>${r.map(v=>`<${head&&i===0?'th':'td'}>${esc(v??'—')}</${head&&i===0?'th':'td'}>`).join('')}</tr></${head&&i===0?'thead':'tbody'}>`).join('')}</table></div>`;
const actionButtons=pid=>`<div class="actions"><button class="btn primary" onclick="fnWorkbook.assessment('${pid}')">Review assessment</button><button class="btn" onclick="fnWorkbook.results('${pid}')">Results</button><button class="btn" onclick="fnDyn.open('${pid}')">Reassessment</button></div>`;
function scenarioPatient(c){const p={...c,'Patient ID':c.patientId,'Display name':'Workbook case '+c.Scenario,'Catheter infection':c['Catheter / skin–soft-tissue infection'],'MASCC score':c['MASCC score'],'Final risk group':c['Risk group'],_workbookScenario:c.Scenario,_syntheticOnly:true};delete p.Scenario;return p}
function install(){if(!data)return;for(const c of data.scenarios){if(!state.customPatients.some(p=>id(p)===c.patientId))state.customPatients.push(scenarioPatient(c));}const byId=new Map(state.results.filter(r=>!r._workbookBaseline).map(r=>[r.eventId,r]));for(const r of [...data.patients.flatMap(p=>FNWorkbookCore.baseline(p,p['Patient ID'],data.version)),...data.scenarios.flatMap(c=>FNWorkbookCore.baseline(c,c.patientId,data.version))])byId.set(r.eventId,r);state.results=[...byId.values()];}
function renderWorkbookPage(){if(!data)return header('Workbook database','Loading the uploaded source workbook…')+(error?`<p class="notice" role="alert">${esc(error)}</p><button class="btn" onclick="fnWorkbook.reload()">Retry</button>`:'');let h=header('Patient database & pathways','One uploaded workbook. Stable patient identity across assessment and results.',`<a class="btn" href="fn-source-workbook.xlsx" download>Source Excel</a>`)+`<div class="banner"><b>${data.counts.patients} primary patients · ${data.counts.scenarios} workbook scenarios · MASCC ${data.index.max}-point index</b><p>Fictional training data. Source medication text and dose bands remain teaching references requiring current local review.</p></div><div class="tabs">${['Patients','Scenarios','Pathways','MASCC Index','Renal reference','Data Dictionary'].map(t=>`<button class="${tab===t?'selected':''}" onclick="fnWorkbook.tab('${t}')">${t}</button>`).join('')}</div>`;
if(tab==='Patients'){const list=data.patients.filter(p=>JSON.stringify(p).toLowerCase().includes(query.toLowerCase()));const maxPage=Math.max(0,Math.ceil(list.length/8)-1);patientPage=Math.min(patientPage,maxPage);h+=`<section class="panel"><div class="sectiontitle"><h2>Primary cohort · ${list.length} matches</h2><input aria-label="Search source patients" placeholder="Patient ID or diagnosis" value="${esc(query)}" onchange="fnWorkbook.search(this.value)"></div><p>Original workbook findings remain separate from saved assessments. Baseline results have no supplied measurement times.</p><div class="scroll"><table><thead><tr><th>Patient / diagnosis</th><th>MASCC</th><th>Risk / modifiers</th><th>Open</th></tr></thead><tbody>${list.slice(patientPage*8,patientPage*8+8).map(p=>{const a=FNWorkbookCore.assessment(p,data.index);return `<tr><td><b>${esc(patientName(p))}</b><br>${esc(p['Patient ID'])} · ${esc(p.Diagnosis)}</td><td>${a.score} / ${data.index.max}<br><small>Source ${p['MASCC score']}</small></td><td>${badge(a.risk)}${a.unstable?'<p>Urgent instability review</p>':''}${a.renal?'<p>Renal risk flag</p>':''}</td><td>${actionButtons(p['Patient ID'])}</td></tr>`}).join('')}</tbody></table></div><div class="pagination"><span>${list.length} records · Page ${patientPage+1} of ${maxPage+1}</span><div><button class="btn" ${patientPage===0?'disabled':''} onclick="fnWorkbook.page(-1)">Previous</button><button class="btn" ${patientPage===maxPage?'disabled':''} onclick="fnWorkbook.page(1)">Next</button></div></div></section>`;}
if(tab==='Scenarios'){const opts=['All','Low risk','High risk','Penicillin allergy','Renal adjustment','Unstable / ICU'];const list=data.scenarios.filter(c=>group==='All'||group==='Renal adjustment'&&c['Renal adjustment needed']==='Yes'||group==='Low risk'&&c['Risk group']==='Low'||group==='High risk'&&c['Risk group']==='High'||group==='Penicillin allergy'&&c['Penicillin allergy']!=='None'||group==='Unstable / ICU'&&c['Unstable (shock / sepsis)']==='Yes');h+=`<section class="panel"><div class="sectiontitle"><h2>Workbook scenarios</h2><select aria-label="Scenario filter" onchange="fnWorkbook.group(this.value)">${opts.map(v=>`<option ${v===group?'selected':''}>${v}</option>`).join('')}</select></div><p>Risk class, allergy and renal modifiers can overlap. Actual source contains 21 scenarios; its dictionary note still mentions 16.</p>${list.map(c=>`<article class="stage"><h3>${esc(c.Scenario)} · ${esc(c.Group)}</h3><p>${esc(c['Clinical vignette'])}</p><p>MASCC ${c['MASCC score']} · ${esc(c['Risk group'])} · CrCl ${c['CrCl (mL/min)']} mL/min · Allergy ${esc(c['Penicillin allergy'])}</p><div class="actions"><button class="btn" onclick="fnWorkbook.scenario('${c.Scenario}')">Source pathway & answer key</button>${actionButtons(c.patientId)}</div></article>`).join('')}</section>`;}
if(tab==='Pathways'){const c=data.scenarios.find(c=>c.Scenario===choice)||data.scenarios[0];h+=`<section class="panel"><h2>Scenario pathway</h2><select aria-label="Workbook scenario" onchange="fnWorkbook.scenario(this.value)">${data.scenarios.map(x=>`<option value="${x.Scenario}" ${x.Scenario===c.Scenario?'selected':''}>${x.Scenario} · ${esc(x.Group)}</option>`).join('')}</select><p>${esc(c['Clinical vignette'])}</p>${actionButtons(c.patientId)}<div class="notice">Imported source teaching pathway. Medication, allergy and renal recommendations have not been adopted as executable rules. Current clinical review remains necessary.</div>${c.steps.map(x=>`<details class="stage"><summary>${x.step} · ${esc(x.title)}</summary><p>${esc(x.action)}</p><small>${esc(x.source)}</small></details>`).join('')}<details><summary>Original workbook outputs and expected answer key</summary>${rowsTable([['Source field','Cached source value'],...Object.entries(c).filter(([k])=>!['steps','patientId'].includes(k)).map(([k,v])=>[k,v])])}<p>A source “Match” means agreement with the workbook answer key, not clinical validation or agreement with current app rules.</p></details></section><section class="panel" style="margin-top:20px"><h2>General pathway references</h2><select aria-label="General pathway" onchange="fnWorkbook.sheet(this.value)">${Object.keys(data.sheets).filter(k=>k.startsWith('PW ')).map(k=>`<option ${sheet===k?'selected':''}>${esc(k)}</option>`).join('')}</select>${rowsTable(data.sheets[sheet].values.filter(r=>r.some(v=>v!==null)))}</section>`;}
if(tab==='MASCC Index'){h+=`<section class="panel"><h2>Primary MASCC reference</h2><p>Points and thresholds come directly from the uploaded MASCC Index. The live assessment also checks clinical overrides. A reassuring score alone does not authorize outpatient care.</p>${rowsTable([['Characteristic','Category / rule','Points'],...data.sheets['MASCC Index'].values.slice(3,12)])}${rowsTable([['Parameter','Value'],['Low-risk score threshold',data.index.lowThreshold],['Age cutoff (below)',data.index.ageCutoff],['SBP point threshold (greater than)',data.index.hypotensionThreshold],['Maximum score',data.index.max]])}<p>Workbook formula snapshots are preserved in the source export. Changing clinical point values requires a reviewed rule release.</p></section>`;}
if(tab==='Renal reference')h+=`<section class="panel"><h2>Imported renal dose reference</h2><div class="notice">Read-only source material, not a new prescribing calculator. Verify renal stability, dialysis, dosing weight and the current local pharmacy protocol in the assessment.</div><button class="btn primary" onclick="fnIntake.open()">Open assessment & renal safety checks</button>${rowsTable(data.sheets['Renal Dosing'].values.filter(r=>r.some(v=>v!==null)),false)}</section>`;
if(tab==='Data Dictionary'){const rr=data.sheets['Data Dictionary'].values,at=rr.findIndex(r=>r[0]==='Column');h+=`<section class="panel"><h2>Source data dictionary</h2><p>Input fields remain distinct from computed points, risk and pathway outputs. Source ranges describe this simulated cohort, not universal clinical validation limits.</p>${rowsTable(rr.slice(at).filter(r=>r[0]))}<h3>Additional scenario fields</h3>${rowsTable([['Field','Source role'],...data.sheets.Scenarios.values[4].map((k,i)=>[k,i<27?'Source input / vignette':i<43?'Workbook formula output':i<52?'Expected teaching answer':i===52?'Workbook agreement check':i===53?'Teaching note':'Workbook renal formula output'])])}<h3>Result linkage</h3>${rowsTable([['Field','Meaning'],['Patient ID','Canonical key shared by source, assessment and result inbox'],['eventId / accession','Stable result-event and report identifiers'],['observedAt / issuedAt','Null for undated workbook baseline, never invented'],['Source / version','Uploaded workbook provenance; preserved original values'],['sourcePatientId','Links a saved entered assessment to its original workbook record']])}<details><summary>Original source notes</summary>${rr.slice(1,at).filter(r=>r[0]).map(r=>`<p><b>${esc(r[0])}:</b> ${esc(r[1])}</p>`).join('')}</details><button class="btn" onclick="fnWorkbook.export()">Export mapped data, dictionary & formulas</button></section>`;}
return h;}
window.fnWorkbook={tab(t){if(['Patients','Scenarios'].includes(t)){go(t==='Patients'?'Overview':'Scenario library');return;}tab=t;go('Workbook database');window.scrollTo(0,0)},page(n){patientPage=Math.max(0,patientPage+n);render();window.scrollTo(0,0)},search(v){query=v;patientPage=0;render()},group(v){group=v;render()},scenario(v){choice=v;tab='Pathways';go('Workbook database')},sheet(v){if(!data.sheets[v]||!v.startsWith('PW '))return;sheet=v;render()},scope(v){if(!['all','primary','secondary'].includes(v))return;scope=v;page=0;search='';filter='All';go('Overview')},results(pid){fnA2A.resultPatient(pid)},assessment(pid){const r=sourceOf(pid);if(!r)return;const key=caseKey(pid),existing=state.customActionCases.find(c=>c.id===key);if(existing){fnIntake.edit(existing);return;}fnIntake.fromWorkbook(FNWorkbookCore.prefill(r,FNIntakeCore.blank()),{patientId:pid,label:r.Scenario?'Workbook case '+r.Scenario:patientName(r),history:(r['Clinical vignette']||'Imported workbook baseline. Verify the current findings before applying a pathway.')+(r['Sepsis: haemodynamic instability or organ dysfunction']==='Yes'?' SOURCE FLAGS: sepsis / organ dysfunction reported. Urgent clinical review and specific current observations are required.':'')+(r['AST/ALT >5× ULN']==='Yes'?' SOURCE FLAGS: AST/ALT >5× ULN reported. Verify liver function.':'')},key)},export(){download('FN_uploaded_workbook_mapping.json',data)},reload:load};
const oldAssess=assess;assess=function(p){if(data&&sourceOf(id(p))&&!p._actionCaseId&&!p._editableAssessment&&!state.assessments[id(p)])return FNWorkbookCore.assessment(sourceOf(id(p)),data.index);return oldAssess(p)};
const oldOverview=overview;overview=function(){if(!data)return oldOverview();const all=patients;const counts={all:all.length,primary:all.filter(primary).length,secondary:all.filter(p=>!primary(p)).length};try{patients=all.filter(inScope);let h=oldOverview();h=h.replace(/<div class="banner"><b>20 named assessment-to-action patients[\s\S]*?<\/div><\/div>/,'');return `<section class="panel" style="margin-bottom:20px"><div class="sectiontitle"><div><h2>Patient database</h2><p>Primary cohort: uploaded workbook patients. Secondary scenarios: workbook scenarios and other saved training cases.</p></div><button class="btn" onclick="fnWorkbook.tab('Scenarios')">${data.counts.scenarios} workbook scenarios & pathways</button></div><div class="cards" role="group" aria-label="Patient groups">${[['all','All patients','All registered training records'],['primary','Primary cohort','Source Excel patient database'],['secondary','Secondary / Hospital scenarios','Additional simulated cases']].map(([key,label,desc])=>`<button class="card" style="text-align:left;cursor:pointer;${scope===key?'outline:2px solid var(--teal,#087f8c)':''}" aria-pressed="${scope===key}" onclick="fnWorkbook.scope('${key}')"><small>${label}</small><b class="number">${counts[key]}</b><p>${desc}</p></button>`).join('')}</div><div class="actions"><button class="btn" onclick="fnWorkbook.tab('MASCC Index')">MASCC Index</button><button class="btn" onclick="fnWorkbook.tab('Data Dictionary')">Data Dictionary</button><button class="btn" onclick="fnWorkbook.tab('Patients')">Source Excel records</button></div><p class="mini">Fictional training data. Group counts reflect the records currently available in this workspace.</p></section>`+h;}finally{patients=all;}};
const oldRows=refreshRows;refreshRows=function(){const all=patients;try{if(data)patients=patients.filter(inScope);return oldRows()}finally{patients=all}};
const oldDetail=detail;detail=function(){let h=oldDetail();if(selected&&sourceOf(id(selected)))h=`<section class="banner"><b>Uploaded workbook record · ${esc(id(selected))}</b><p>Baseline values have no observation time. No culture result is inferred. New assessments retain this patient identity.</p>${actionButtons(id(selected))}</section>`+h;return h;};
const oldRender=render;render=function(){install();oldRender();if(view==='Workbook database')$('#app').innerHTML=renderWorkbookPage();};
async function load(){try{const r=await fetch('workbook-data.json',{cache:'no-store'});if(!r.ok)throw Error('Uploaded workbook could not be loaded');const next=await r.json();if(next.patients.length!==next.counts.patients||next.scenarios.length!==next.counts.scenarios||new Set([...next.patients.map(p=>p['Patient ID']),...next.scenarios.map(c=>c.patientId)]).size!==next.counts.patients+next.counts.scenarios)throw Error('Workbook identity validation failed');data=next;error='';install();render()}catch(e){error=e.message;if(view==='Workbook database')render()}}load();
})();
